package org.sleepwell.app;
/** Three fresh matching frames, never a confirmation toggle or a cached result. */
final class PictureHold {private final PictureSignature reference;private PictureSignature previous;private long first,last=-1;private int count;PictureHold(PictureSignature reference){this.reference=reference;}void reset(){count=0;first=0;last=-1;previous=null;}boolean frame(PictureSignature sample,long captured,long now){if(sample==null||captured<0||captured>now||now-captured>800||captured<=last||!reference.matches(sample)){reset();return false;}if(previous==null||captured-last>400||!previous.matches(sample)){count=0;first=captured;}previous=sample;last=captured;count++;return count>=3&&captured-first>=400;}int progress(){return Math.min(3,count);}static long captured(long sensorNanos,long elapsed,long monotonic){if(sensorNanos<=0)return -1;long sensor=sensorNanos/1000000L;for(long now:new long[]{elapsed,monotonic}){long age=now-sensor;if(age>=0&&age<=800)return elapsed-age;}return -1;}}
